// -------------------------------------------------------------
// SEGURIDAD: FORZAR HTTPS & CABECERAS PROTEGIDAS (PCI-DSS & HSTS)
// -------------------------------------------------------------
app.use((req: Request, res: Response, next) => {
  const proto = req.headers["x-forwarded-proto"];
  const host = req.headers.host;
  
  // Redirección permanente 301 a HTTPS en entornos de producción
  if (process.env.NODE_ENV === "production" && proto && proto !== "https" && host && !host.includes("localhost") && !host.includes("127.0.0.1")) {
    return res.redirect(301, `https://${host}${req.url}`);
  }

  // Cabeceras HTTP de Seguridad
  res.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains; preload");
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "SAMEORIGIN");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");

  // Optimización de Velocidad y Caché para Archivos Estáticos
  if (req.url.match(/\.(svg|png|jpg|jpeg|webp|woff2|woff|ttf|ico)$/)) {
    res.setHeader("Cache-Control", "public, max-age=604800, stale-while-revalidate=86400");
  }
  next();
});

