const adminSessions = new Map<string, { createdAt: number; expiresAt: number }>();

function generateAdminSessionToken(): string {
  const token = crypto.randomBytes(32).toString("hex");
  const now = Date.now();
  adminSessions.set(token, { createdAt: now, expiresAt: now + 24 * 60 * 60 * 1000 });
  return token;
}

function validateAdminToken(token?: string): boolean {
  if (!token) return false;
  const session = adminSessions.get(token);
  if (!session) return false;
  if (Date.now() > session.expiresAt) {
    adminSessions.delete(token);
    return false;
  }
  return true;
}

function requireAdminAuth(req: Request, res: Response, next: any) {
  const authHeader = req.headers["authorization"] || "";
  const token = authHeader.startsWith("Bearer ")
    ? authHeader.slice(7).trim()
    : (req.headers["x-admin-token"] as string) || (req.query.adminToken as string) || "";

  if (!token || !validateAdminToken(token)) {
    return res.status(401).json({
      error: "Acceso denegado. Se requiere autenticación de administrador válida.",
    });
  }
  next();
}

// Persistencia segura de credenciales con hashing scrypt criptográfico con salt aleatorio
const USERS_FILE_PATH = path.join(process.cwd(), "web_users.json");

function hashPassword(password: string): string {
  if (!password) return "";
  const salt = crypto.randomBytes(16).toString("hex");
  const hash = crypto.scryptSync(password.trim(), salt, 64).toString("hex");
  return `scrypt:${salt}:${hash}`;
}

function verifyPassword(password: string, storedHashOrPlain?: string): boolean {
  if (!password || !storedHashOrPlain) return false;
  const clean = password.trim();

  // Formato scrypt con salt
  if (storedHashOrPlain.startsWith("scrypt:")) {
    const parts = storedHashOrPlain.split(":");
    if (parts.length === 3) {
      const salt = parts[1];
      const expected = parts[2];
      try {
        const hash = crypto.scryptSync(clean, salt, 64).toString("hex");
        return crypto.timingSafeEqual(Buffer.from(hash, "hex"), Buffer.from(expected, "hex"));
      } catch {
        return false;
      }
    }
  }

  // Compatibilidad con hashes legacy SHA-256 (64 hex caracteres)
  if (/^[a-f0-9]{64}$/i.test(storedHashOrPlain)) {
    const sha256 = crypto.createHash("sha256").update(clean).digest("hex");
    return sha256.toLowerCase() === storedHashOrPlain.toLowerCase();
  }

  // Compatibilidad temporal texto plano legacy
  return clean === storedHashOrPlain;
}

