// Registro Oficial de Cliente Web sincronizado 100% con Loyverse POS
app.post("/api/customers/register-web", async (req: Request, res: Response) => {
  try {
    const { name, email, phone, city, address, document, password } = req.body;
    if (!name || !email) {
      return res.status(400).json({ error: "Nombre y correo son requeridos" });
    }

    const cleanEmail = email.trim().toLowerCase();
    const cleanPhone = (phone || "").trim().replace(/\D/g, "");
    const cleanDocument = (document || "").trim().replace(/\D/g, "");
    const passwordHash = password ? hashPassword(password) : "";
    let loyverseCustomer: any = null;

    if (activeLoyverseToken) {
      try {
        // 1. Buscar si ya existe en Loyverse POS por correo, teléfono o cédula
        const listData = await callLoyverseApi("/customers?limit=250");
        const existing = (listData.customers || []).find((c: any) =>
          (c.email && c.email.toLowerCase() === cleanEmail) ||
          (cleanPhone && c.phone_number && c.phone_number.replace(/\D/g, "") === cleanPhone) ||
          (cleanDocument && c.customer_code && c.customer_code === cleanDocument)
        );

        const targetCity = (city && city.trim()) || existing?.city || "";
        const targetAddress = (address && address.trim()) || existing?.address || "";
        const targetDoc = cleanDocument || (existing?.customer_code && !existing.customer_code.startsWith("WEB-") ? existing.customer_code : "");

        const buildNote = (baseNote?: string) => {
          let cleanBase = (baseNote || "")
            .replace(/\[PW_(?:WEB|HASH):[^\]]+\]/gi, "")
            .replace(/CC:\s*[^|•]+/gi, "")
            .replace(/Ciudad:\s*[^|•]+/gi, "")
            .replace(/Dir:\s*[^|•]+/gi, "")
            .replace(/Cliente Web URBANNOISE[^|•]*/gi, "")
            .replace(/•|\|/g, " ")
            .trim();
          const parts = [];
          if (targetDoc) parts.push(`CC: ${targetDoc}`);
          if (targetCity) parts.push(`Ciudad: ${targetCity}`);
          if (targetAddress) parts.push(`Dir: ${targetAddress}`);
          parts.push("Cliente Web URBANNOISE");
          if (passwordHash) parts.push(`[PW_WEB:${passwordHash}]`);
          if (cleanBase) parts.push(cleanBase);
          return parts.join(" | ");
        };

        if (existing) {
          loyverseCustomer = existing;
          await callLoyverseApi(`/customers/${existing.id}`, {
            method: "POST",
            body: {
              ...existing,
              note: buildNote(existing.note),
              customer_code: targetDoc || undefined,
              phone_number: cleanPhone || existing.phone_number,
              address: targetAddress || existing.address,
              city: targetCity || existing.city,
            },
          }).catch(() => {});
        } else {
          // 2. Crear nuevo cliente en Loyverse POS con tag Web oficial, Cédula, Ciudad, Dirección y Hash en Note
          const customerPayload: any = {
            name: name.trim().toUpperCase(),
            email: cleanEmail,
            note: buildNote(),
            customer_code: targetDoc || `WEB-${Math.floor(100000 + Math.random() * 900000)}`,
          };
          if (cleanPhone) customerPayload.phone_number = cleanPhone;
          if (targetAddress) customerPayload.address = targetAddress;
          if (targetCity) customerPayload.city = targetCity;

          loyverseCustomer = await callLoyverseApi("/customers", {
            method: "POST",
            body: customerPayload,
          });
        }
      } catch (apiErr: any) {
        console.warn("[Loyverse] Error al sincronizar cliente en Loyverse:", apiErr.message);
      }
    }

    const customerId = loyverseCustomer?.id || `web-cust-${Date.now()}`;

    // Almacenar credenciales web locales con hash criptográfico SHA-256
    webUsersStore[cleanEmail] = {
      id: customerId,
      name: name.trim().toUpperCase(),
      email: cleanEmail,
      phone: cleanPhone,
      document: cleanDocument,
      city: city || "Bogotá, D.C.",
      address: address || "",
      passwordHash,
      loyverseCustomerId: customerId,
      createdAt: new Date().toISOString(),
    };
    saveWebUsersStore();

    res.json({
      success: true,
      customer: {
        id: customerId,
        name: name.trim().toUpperCase(),
        email: cleanEmail,
        phone: cleanPhone,
        document: cleanDocument,
        city: city || "Bogotá, D.C.",
        address: address || "",
        loyverseCustomerId: customerId,
        totalSpent: loyverseCustomer?.total_spent || 0,
        totalVisits: loyverseCustomer?.total_visits || 0,
        syncedToLoyverse: Boolean(loyverseCustomer?.id),
        createdAt: new Date().toISOString(),
      },
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

