app.post("/api/customers/login-web", rateLimit(60000, 10), async (req: Request, res: Response) => {
  try {
    const { emailOrPhone, password } = req.body;
    if (!emailOrPhone) {
      return res.status(400).json({ error: "Ingresa tu correo o teléfono" });
    }
    if (!password || typeof password !== "string" || !password.trim()) {
      return res.status(400).json({ error: "Ingresa tu contraseña para acceder a tu cuenta." });
    }

    const query = emailOrPhone.trim().toLowerCase();
    const queryDigits = query.replace(/\D/g, "");

    let localUser = Object.values(webUsersStore).find((u: any) =>
      u.email.toLowerCase() === query ||
      matchPhone(u.phone, query)
    );

    let loyverseCustomer: any = null;
    if (activeLoyverseToken) {
      try {
        const listData = await callLoyverseApi("/customers?limit=250");
        loyverseCustomer = (listData.customers || []).find((c: any) =>
          (c.email && c.email.toLowerCase() === query) ||
          matchPhone(c.phone_number, query)
        );
      } catch {}
    }

    if (!localUser && !loyverseCustomer) {
      return res.status(404).json({
        error: "No encontramos ninguna cuenta asociada a este correo o teléfono. Por favor regístrate para continuar.",
      });
    }

    // Validación de Contraseña (soporta almacenamiento seguro scrypt en notas de Loyverse)
    const noteHashMatch = loyverseCustomer?.note?.match(/\[PW_(?:WEB|HASH):([^\]]+)\]/i);
    const loyverseSavedHash = noteHashMatch ? noteHashMatch[1] : null;

    if (localUser && (localUser.passwordHash || localUser.password)) {
      const isMatch = verifyPassword(password, localUser.passwordHash || localUser.password);
      if (!isMatch) {
        return res.status(401).json({ error: "Contraseña incorrecta. Por favor verifica tus credenciales." });
      }
      // Actualizar automáticamente a scrypt si aún era legacy SHA-256
      if (!localUser.passwordHash || !localUser.passwordHash.startsWith("scrypt:")) {
        localUser.passwordHash = hashPassword(password);
        saveWebUsersStore();
      }
      // Si la nota en Loyverse no tiene el hash o está desactualizada, sincronizarla hacia Loyverse
      if (activeLoyverseToken && loyverseCustomer && loyverseSavedHash !== localUser.passwordHash) {
        const cleanBase = (loyverseCustomer.note || "")
          .replace(/\[PW_(?:WEB|HASH):[^\]]+\]/gi, "")
          .trim();
        const updatedNote = cleanBase ? `${cleanBase} | [PW_WEB:${localUser.passwordHash}]` : `[PW_WEB:${localUser.passwordHash}]`;
        callLoyverseApi(`/customers/${loyverseCustomer.id}`, {
          method: "POST",
          body: {
            ...loyverseCustomer,
            note: updatedNote,
          },
        }).catch(() => {});
      }
    } else if (loyverseSavedHash) {
      const isMatch = verifyPassword(password, loyverseSavedHash);
      if (!isMatch) {
        return res.status(401).json({ error: "Contraseña incorrecta. Por favor verifica tus credenciales." });
      }
      // Re-poblar webUsersStore en memoria/disco desde Loyverse
      webUsersStore[query] = {
        id: loyverseCustomer.id,
        name: loyverseCustomer.name,
        email: loyverseCustomer.email || query,
        phone: loyverseCustomer.phone_number || "",
        document: loyverseCustomer.customer_code || "",
        city: loyverseCustomer.city || "Bogotá, D.C.",
        address: loyverseCustomer.address || "",
        passwordHash: loyverseSavedHash,
        loyverseCustomerId: loyverseCustomer.id,
        createdAt: loyverseCustomer.created_at || new Date().toISOString(),
      };
      saveWebUsersStore();
    } else {
      return res.status(403).json({
        error: "Esta cuenta fue registrada en nuestra tienda física sin clave web. Por favor usa la opción 'Crear Cuenta' o 'Registrarse' con tu correo para asignar tu clave.",
      });
    }

    const docMatch = loyverseCustomer?.note?.match(/CC:\s*([0-9]+)/i);
    const finalName = localUser?.name || loyverseCustomer?.name || query.split("@")[0].toUpperCase();
    const finalEmail = localUser?.email || loyverseCustomer?.email || query;
    const finalPhone = localUser?.phone || loyverseCustomer?.phone_number || "";
    const finalCity = localUser?.city || loyverseCustomer?.city || "Bogotá, D.C.";
    const finalAddress = localUser?.address || loyverseCustomer?.address || "";
    const finalDocument = localUser?.document || (loyverseCustomer?.customer_code && !loyverseCustomer.customer_code.startsWith("WEB-") ? loyverseCustomer.customer_code : "") || (docMatch ? docMatch[1] : "");
    const finalId = loyverseCustomer?.id || localUser?.id || `web-${Date.now()}`;

    res.json({
      success: true,
      customer: {
        id: finalId,
        name: finalName,
        email: finalEmail,
        phone: finalPhone,
        document: finalDocument,
        city: finalCity,
        address: finalAddress,
        totalSpent: loyverseCustomer?.total_spent || 0,
        totalVisits: loyverseCustomer?.total_visits || 0,
        loyverseCustomerId: loyverseCustomer?.id,
        createdAt: loyverseCustomer?.created_at || localUser?.createdAt || new Date().toISOString(),
      },
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

