// 9b. Proxy para servir imágenes alojadas en GitHub (Soporta repositorios Públicos y Privados)
app.get("/api/github/image", async (req: Request, res: Response) => {
  try {
    const filePath = req.query.path as string;
    if (!filePath) return res.status(400).send("El parámetro 'path' es requerido");

    const cleanPath = filePath.replace(/^\/+/, "").replace(/\\/g, "/");

    // Restricción estricta de rutas permitidas y extensiones de imagen válidas
    if (
      cleanPath.includes("..") ||
      !cleanPath.match(/^(images|catalog|assets)\/.*\.(jpg|jpeg|png|webp|svg|gif|ico)$/i)
    ) {
      return res.status(403).send("Ruta de archivo no autorizada. Solo se permiten imágenes del catálogo.");
    }

    const owner = process.env.VITE_GITHUB_OWNER || "tusoporteapp";
    const repo = process.env.VITE_GITHUB_REPO || "urbannoise";
    const token = process.env.VITE_GITHUB_TOKEN || "";

    const headers: Record<string, string> = {
      Accept: "application/vnd.github.v3+json",
      "User-Agent": "URBANNOISE-Web-Server",
    };
    if (token) {
      headers["Authorization"] = `Bearer ${token}`;
    }

    const ghRes = await fetch(`https://api.github.com/repos/${owner}/${repo}/contents/${cleanPath}`, {
      headers,
    });

    if (!ghRes.ok) {
      return res.status(ghRes.status).send(`No se encontró el archivo en GitHub: ${ghRes.statusText}`);
    }

    const fileData: any = await ghRes.json();
    if (!fileData.content) {
      return res.status(404).send("Contenido de archivo vacío");
    }

    const buf = Buffer.from(fileData.content, "base64");
    const ext = cleanPath.split(".").pop()?.toLowerCase() || "jpg";
    const mimeMap: Record<string, string> = {
      jpg: "image/jpeg",
      jpeg: "image/jpeg",
      png: "image/png",
      webp: "image/webp",
      gif: "image/gif",
      svg: "image/svg+xml",
    };
    res.setHeader("Content-Type", mimeMap[ext] || "image/jpeg");
    res.setHeader("Cache-Control", "public, max-age=86400, stale-while-revalidate=604800");
    return res.send(buf);
  } catch (error: any) {
    return res.status(500).send(error.message);
  }
});

