let activeServientregaBearerToken = process.env.SERVIENTREGA_BEARER_TOKEN || "";
let activeServientregaEnv: "sandbox" | "prod" = (process.env.SERVIENTREGA_ENV as any) || "sandbox";

app.get("/api/shipping/servientrega/status", (req: Request, res: Response) => {
  res.json({
    configured: Boolean(activeServientregaClientKey && activeServientregaBearerToken),
    env: activeServientregaEnv,
    hasClientKey: Boolean(activeServientregaClientKey),
    hasBearerToken: Boolean(activeServientregaBearerToken),
    docUrl: "https://www.servientregaapi.com/docs/public",
  });
});

app.post("/api/shipping/servientrega/configure", requireAdminAuth, (req: Request, res: Response) => {
  const { clientKey, bearerToken, env } = req.body;
  if (clientKey !== undefined) activeServientregaClientKey = String(clientKey).trim();
  if (bearerToken !== undefined) activeServientregaBearerToken = String(bearerToken).trim();
  if (env === "prod" || env === "sandbox") activeServientregaEnv = env;

  res.json({
    success: true,
    message: "Credenciales de Servientrega API actualizadas correctamente.",
    configured: Boolean(activeServientregaClientKey && activeServientregaBearerToken),
    env: activeServientregaEnv,
  });
});

app.get("/api/shipping/servientrega/tracking/:guia", rateLimit(60000, 30), async (req: Request, res: Response) => {
  try {
    const rawGuia = req.params.guia;
    const cleanGuia = String(rawGuia || "").trim();

    if (!cleanGuia) {
      return res.status(400).json({ success: false, error: "El número de guía es requerido." });
    }

    if (!activeServientregaClientKey || !activeServientregaBearerToken) {
      return res.status(400).json({
        success: false,
        configured: false,
        error: "Servientrega API no está configurada aún en el servidor.",
        details: "Se requiere 'clientKey' y 'Bearer Token' proporcionados por Servientrega según https://www.servientregaapi.com/docs/public",
      });
    }

    const targetUrl = `https://www.servientregaapi.com/public/integration/${encodeURIComponent(
      activeServientregaClientKey
    )}/siscore/guias/tracking/${encodeURIComponent(cleanGuia)}?env=${activeServientregaEnv}`;

    const apiRes = await fetch(targetUrl, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${activeServientregaBearerToken}`,
        "Content-Type": "application/json",
      },
    });

    const data = await apiRes.json().catch(() => null);

    if (!apiRes.ok) {
      return res.status(apiRes.status).json({
        success: false,
        status: apiRes.status,
        error: data?.message || data?.error || `Error ${apiRes.status} de Servientrega API`,
        data,
      });
    }

    res.json({
      success: true,
      guia: cleanGuia,
      tracking: data,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message || "Error al conectar con la API de Servientrega",
    });
  }
});

// 14. CONFIRMAR PEDIDO, GENERAR RECIBO EN LOYVERSE Y DESCONTAR INVENTARIO
app.post("/api/orders/confirm-and-sync", rateLimit(60000, 20), async (req: Request, res: Response) => {
  try {
    const {
      orderId,
      amount,
      currency = "COP",
      paymentMethod = "bold_pse",
      boldTransaction,
      customer,
      items = [],
      totals = {},
      shippingAddress = {},
    } = req.body;

    if (!orderId) {
      return res.status(400).json({ error: "orderId es requerido" });
    }

    const orderAmount = Number(totals.total || amount || 0);

    // Validación de Integridad de Pago
    const isCod = paymentMethod === "cod";
    if (!isCod) {
      if (!boldTransaction || boldTransaction.status !== "APROBADA") {
        return res.status(400).json({
          error: "No se puede confirmar el pedido sin una transacción de pago aprobada.",
        });
      }
      if (activeBoldSecretKey && boldTransaction.integritySignature) {
        const rawStringToSign = `${orderId}${orderAmount}${currency}${activeBoldSecretKey}`;
        const computedSignature = crypto.createHash("sha256").update(rawStringToSign).digest("hex");
        if (computedSignature !== boldTransaction.integritySignature) {
          return res.status(400).json({
            error: "Firma criptográfica de integridad de la transacción no coincide.",
          });
        }
      }
    }

    // 1. Descontar Inventario Inmediatamente en Servidor
    const deductedStockInfo: any[] = [];
    for (const it of items) {
      const qty = Number(it.qty) || 1;
      const currentStock = it.stock !== undefined ? Number(it.stock) : 10;

      if (it.sku) {
        const prev = inventoryOverrides[it.sku] ?? currentStock;
        const newStock = Math.max(0, prev - qty);
        inventoryOverrides[it.sku] = newStock;
        deductedStockInfo.push({ item: it.name, sku: it.sku, qtyDeducted: qty, remainingStock: newStock });
      }
      if (it.loyverseVariantId) {
        const prev = inventoryOverrides[it.loyverseVariantId] ?? currentStock;
        inventoryOverrides[it.loyverseVariantId] = Math.max(0, prev - qty);
      }
      if (it.id) {
        const prev = inventoryOverrides[it.id] ?? currentStock;
        inventoryOverrides[it.id] = Math.max(0, prev - qty);
      }
    }

    // 2. Generar Recibo Oficial en Loyverse POS
    let loyverseReceiptResult: any = null;
    let loyverseSyncStatus: "SUCCESS" | "SIMULATED" | "ERROR" = "SIMULATED";
    let loyverseErrorMessage: string | null = null;

    if (activeLoyverseToken) {
      try {
        const storeId = await getDefaultStoreId();

        const lineItems = items.map((it: any) => {
          const unitPrice = Number(it.price) || 0;
          const qty = Number(it.qty) || 1;
          const lineTotal = unitPrice * qty;

          const itemPayload: any = {
            item_name: it.name || "Prenda URBANNOISE",
            variant_name: it.size || "Talla Única",
            quantity: qty,
            price: unitPrice,
            gross_total_money: lineTotal,
            total_money: lineTotal,
          };

          if (it.loyverseVariantId) {
            itemPayload.variant_id = it.loyverseVariantId;
          }

          return itemPayload;
        });

        // Vincular o crear cliente en Loyverse POS para acumulación de historial de ventas
        let attachedCustomerId: string | null = customer?.loyverseCustomerId || null;

        if (!attachedCustomerId && (customer?.email || customer?.phone)) {
          try {
            const cleanEmail = (customer.email || "").trim().toLowerCase();
            const cleanPhone = (customer.phone || "").trim().replace(/\D/g, "");

            const listData = await callLoyverseApi("/customers?limit=250");
            const existing = (listData.customers || []).find((c: any) =>
              (cleanEmail && c.email && c.email.toLowerCase() === cleanEmail) ||
              (cleanPhone && c.phone_number && c.phone_number.replace(/\D/g, "") === cleanPhone)
            );

            const cCity = customer.city || shippingAddress?.city || "";
            const cAddr = customer.address || shippingAddress?.address || "";
            const cleanDoc = (customer.document || "").trim().replace(/\D/g, "");
            const existingHash = (cleanEmail && webUsersStore[cleanEmail]?.passwordHash) || "";

            const buildCheckoutNote = (baseNote?: string) => {
              let cleanBase = (baseNote || "")
                .replace(/\[PW_(?:WEB|HASH):[^\]]+\]/gi, "")
                .replace(/CC:\s*[^|•]+/gi, "")
                .replace(/Ciudad:\s*[^|•]+/gi, "")
                .replace(/Dir:\s*[^|•]+/gi, "")
                .replace(/Cliente Web URBANNOISE[^|•]*/gi, "")
                .replace(/•|\|/g, " ")
                .trim();
              const parts = [];
              if (cleanDoc) parts.push(`CC: ${cleanDoc}`);
              if (cCity) parts.push(`Ciudad: ${cCity}`);
              if (cAddr) parts.push(`Dir: ${cAddr}`);
              parts.push("Cliente Web URBANNOISE");
              if (existingHash) parts.push(`[PW_WEB:${existingHash}]`);
              if (cleanBase) parts.push(cleanBase);
              return parts.join(" | ");
            };

            if (existing) {
              attachedCustomerId = existing.id;
              await callLoyverseApi(`/customers/${existing.id}`, {
                method: "POST",
                body: {
                  ...existing,
                  note: buildCheckoutNote(existing.note),
                  customer_code: existing.customer_code || cleanDoc || undefined,
                  phone_number: cleanPhone || existing.phone_number,
                  address: cAddr || existing.address,
                  city: cCity || existing.city,
                },
              }).catch(() => {});
            } else if (customer.name && (cleanEmail || cleanPhone)) {
              const newCustPayload: any = {
                name: customer.name.trim().toUpperCase(),
                email: cleanEmail || undefined,
                note: buildCheckoutNote(),
                customer_code: cleanDoc || `WEB-${Math.floor(100000 + Math.random() * 900000)}`,
              };
              if (cleanPhone) newCustPayload.phone_number = cleanPhone;
              if (cAddr) newCustPayload.address = cAddr;
              if (cCity) newCustPayload.city = cCity;

              const createdCust = await callLoyverseApi("/customers", {
                method: "POST",
                body: newCustPayload,
              });
              if (createdCust?.id) {
                attachedCustomerId = createdCust.id;
              }
            }
          } catch (custErr: any) {
            console.warn("[Loyverse] Advertencia vinculando cliente a la venta:", custErr.message);
          }
        }

        if (customer?.email) {
          const cEmail = customer.email.trim().toLowerCase();
          const cDoc = (customer.document || "").trim().replace(/\D/g, "");
          if (!webUsersStore[cEmail]) {
            webUsersStore[cEmail] = {
              id: attachedCustomerId || `web-cust-${Date.now()}`,
              name: (customer.name || "Cliente").trim().toUpperCase(),
              email: cEmail,
              phone: customer.phone || "",
              document: cDoc,
              city: customer.city || shippingAddress?.city || "Bogotá, D.C.",
              address: customer.address || shippingAddress?.address || "",
              loyverseCustomerId: attachedCustomerId,
              createdAt: new Date().toISOString(),
            };
            saveWebUsersStore();
          } else if (attachedCustomerId) {
            webUsersStore[cEmail].loyverseCustomerId = attachedCustomerId;
            if (cDoc && !webUsersStore[cEmail].document) webUsersStore[cEmail].document = cDoc;
            saveWebUsersStore();
          }
        }

        const receiptPayload: any = {
          receipt_type: "SELL",
          order: orderId,
          created_at: new Date().toISOString(),
          note: `URBANNOISE Web #${orderId} • Pasarela Bold: Ref ${boldTransaction?.boldReference || "BLD-DIRECT"} • Cliente: ${customer?.name || "Cliente"} - CC ${customer?.document || "N/A"} - Tel ${customer?.phone || ""}`,
          line_items: lineItems,
          payments: [
            {
              payment_name: `Bold.co (${paymentMethod})`,
              type: paymentMethod === "cod" ? "CASH" : "OTHER",
              paid_at: new Date().toISOString(),
              money_amount: orderAmount,
            },
          ],
          total_money: orderAmount,
        };

        if (totals?.discount && Number(totals.discount) > 0) {
          receiptPayload.total_discount = Number(totals.discount);
          receiptPayload.note += ` • Descuento: -$${totals.discount}`;
        }

        if (attachedCustomerId) {
          receiptPayload.customer_id = attachedCustomerId;
        }

        if (storeId) {
          receiptPayload.store_id = storeId;
        }

        const apiRes = await callLoyverseApi("/receipts", {
          method: "POST",
          body: receiptPayload,
        });

        loyverseReceiptResult = {
          id: apiRes.receipt?.id || apiRes.id || `REC-${Date.now()}`,
          receipt_number: apiRes.receipt?.receipt_number || apiRes.receipt_number || `REC-${orderId}`,
          created_at: apiRes.receipt?.created_at || new Date().toISOString(),
          total_money: orderAmount,
          syncedToPos: true,
        };
        loyverseSyncStatus = "SUCCESS";

        // Ajuste directo opcional en Loyverse Inventory
        if (storeId) {
          const invUpdates = items
            .filter((it: any) => it.loyverseVariantId)
            .map((it: any) => ({
              variant_id: it.loyverseVariantId,
              store_id: storeId,
              in_stock: inventoryOverrides[it.loyverseVariantId] ?? 0,
            }));

          if (invUpdates.length > 0) {
            await callLoyverseApi("/inventory", {
              method: "POST",
              body: { inventory_levels: invUpdates },
            }).catch((e) => console.warn("[Loyverse] Inventario ajustado vía recibo SELL:", e.message));
          }
        }
      } catch (err: any) {
        console.error("[Loyverse] Error creando recibo oficial:", err.message);
        loyverseErrorMessage = err.message;
        loyverseSyncStatus = "ERROR";
      }
    }

    // Si no había token o falló el API externo, proveer recibo local simulado con trazabilidad
    if (!loyverseReceiptResult) {
      loyverseReceiptResult = {
        id: `LOY-REC-${orderId}`,
        receipt_number: `REC-${Date.now().toString().slice(-6)}`,
        created_at: new Date().toISOString(),
        total_money: orderAmount,
        syncedToPos: false,
        note: activeLoyverseToken
          ? `Error al enviar a Loyverse POS: ${loyverseErrorMessage}`
          : "Recibo emitido localmente con descuento de stock en tienda. Configura LOYVERSE_API_TOKEN en el panel para sincronizar con tu terminal físico.",
      };
    }

    // 3. Registrar Orden Completa en Historial
    const orderRecord = {
      orderId,
      amount: orderAmount,
      currency,
      paymentMethod,
      customer: customer || {},
      shippingAddress: shippingAddress || {},
      items: items.map((i: any) => ({
        id: i.id,
        name: i.name,
        size: i.size,
        qty: i.qty,
        price: i.price,
        sku: i.sku,
        loyverseVariantId: i.loyverseVariantId,
      })),
      totals,
      boldTransaction: boldTransaction || {
        boldTransactionId: `TX-BOLD-${Date.now().toString(36).toUpperCase()}`,
        boldReference: `BLD${Math.floor(10000000 + Math.random() * 90000000)}`,
        authorizationCode: `${Math.floor(100000 + Math.random() * 900000)}`,
        status: "APROBADA",
      },
      loyverseReceipt: loyverseReceiptResult,
      loyverseSyncStatus,
      createdAt: new Date().toISOString(),
    };

    recentOrders.unshift(orderRecord);
    if (recentOrders.length > 100) recentOrders.pop();

    res.json({
      success: true,
      orderId,
      order: orderRecord,
      boldTransaction: orderRecord.boldTransaction,
      loyverseReceipt: loyverseReceiptResult,
      loyverseSyncStatus,
      inventoryDeducted: true,
      deductedStockInfo,
    });
  } catch (error: any) {
    console.error("[Confirm & Sync Error]", error);
    res.status(500).json({ error: error.message });
  }
});

// 15. Webhook Oficial de Bold.co
app.post("/api/bold/webhook", async (req: Request, res: Response) => {
  try {
    const payload = req.body;
    const event = {
      receivedAt: new Date().toISOString(),
      headers: req.headers,
      payload,
    };

    recentBoldWebhooks.unshift(event);
    if (recentBoldWebhooks.length > 50) recentBoldWebhooks.pop();

    console.log("[Bold Webhook Recibido]", payload?.event || "evento");

    // Si el evento de Bold es pago aprobado y viene con referencia de orden:
    if (payload?.event === "payment.approved" || payload?.status === "APPROVED") {
      const reference = payload?.data?.reference || payload?.reference;
      console.log(`[Bold Webhook] Pago aprobado para referencia: ${reference}`);
    }

    res.status(200).json({ received: true });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

